using Microsoft.EntityFrameworkCore;
namespace Decont;

public class ReportReset { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ReportId { get; set; } public string Json { get; set; } = "{}"; public string Actor { get; set; } = ""; public string Reason { get; set; } = ""; public DateTime At { get; set; } = DateTime.UtcNow; }
public class ReportRestore { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ResetId { get; set; } public string Actor { get; set; } = ""; public string Reason { get; set; } = ""; public DateTime At { get; set; } = DateTime.UtcNow; }
public record ResetCommand(long Version, string Confirmation, string Reason);
public record ResetContent(string? Payment, Guid? CardId, List<Guid> Lines, Dictionary<Guid, string> Groups);
public static class ReportResets
{
    public static void Map(RouteGroupBuilder api)
    {
        api.MapGet("/reports/{id:guid}/resets", async (Guid id, Db db, Reports svc, HttpContext c) => { await svc.Get(id, c.User); return new { resets = await db.ReportResets.Where(x => x.ReportId == id).OrderByDescending(x => x.At).ToListAsync(), restores = await db.ReportRestores.Where(x => db.ReportResets.Any(r => r.Id == x.ResetId && r.ReportId == id)).ToListAsync() }; });
        api.MapPost("/reports/{id:guid}/reset", async (Guid id, ResetCommand i, Db db, Reports svc, HttpContext c) => await Api.Atomic(db, c, i, async () => { var report = await svc.Version(id, i.Version, c.User); svc.Edit(report, c.User, i.Reason); Guard.Reason(i.Reason); Guard.Require(i.Confirmation == report.Number, "reset_confirmation", "Scrie numărul decontului pentru a confirma golirea reversibilă.", "Type the report number to confirm reversible reset."); var lines = report.Lines.Where(l => !l.Archived).ToList(); Guard.Require(lines.Count > 0, "reset_empty", "Decontul este deja gol.", "Report is already empty."); var ids = lines.Select(l => l.Id).ToList(); Guard.Require(!await db.Matches.AnyAsync(m => ids.Contains(m.LineId)), "reset_matches", "Anulează alocările bancare înainte de golire.", "Undo bank allocations before resetting."); var groups = await db.DocumentGroups.Where(g => g.ExpenseId != null && ids.Contains(g.ExpenseId.Value)).ToListAsync(); var reset = new ReportReset { ReportId = id, Json = Serialization.Write(new ResetContent(report.Payment, report.CardId, ids, groups.ToDictionary(g => g.Id, g => g.State))), Actor = Reports.Actor(c.User), Reason = i.Reason }; db.ReportResets.Add(reset); foreach (var line in lines) { line.Archived = true; FinancialCalculations.Invalidate(line, true); } foreach (var group in groups) group.State = "Archived"; Reports.Touch(report); svc.Log(c.User, id, reset.Id.ToString(), "ReportReset", after: new { reset.Id, lines = ids }, reason: i.Reason); return new { resetId = reset.Id, report = Api.View(report) }; }));
        api.MapPost("/reports/{id:guid}/resets/{reset:guid}/restore", async (Guid id, Guid reset, ResetCommand i, Db db, Reports svc, HttpContext c) => await Api.Atomic(db, c, i, async () => { var report = await svc.Version(id, i.Version, c.User); svc.Edit(report, c.User, i.Reason); Guard.Reason(i.Reason); Guard.Require(i.Confirmation == report.Number, "reset_confirmation", "Scrie numărul decontului pentru restaurare.", "Type the report number to restore."); var record = await db.ReportResets.SingleOrDefaultAsync(r => r.Id == reset && r.ReportId == id); Guard.Require(record != null, "not_found", "Golirea nu există.", "Reset not found.", 404); Guard.Require(!await db.ReportRestores.AnyAsync(x => x.ResetId == reset) && !report.Lines.Any(l => !l.Archived), "restore_conflict", "Decontul trebuie să fie gol și golirea să nu fi fost deja restaurată.", "Report must be empty and reset must not already be restored.", 409); var content = Serialization.Read<ResetContent>(record!.Json); Guard.Require(content.Lines.Count <= Rules.MaxLines && content.Lines.All(x => report.Lines.Any(l => l.Id == x)), "restore_integrity", "Datele de restaurare nu sunt complete.", "Restore data is incomplete.", 409); report.Payment = content.Payment; report.CardId = content.CardId; foreach (var line in report.Lines.Where(l => content.Lines.Contains(l.Id))) { line.Archived = false; FinancialCalculations.Invalidate(line, true); } var groups = await db.DocumentGroups.Where(g => content.Groups.Keys.Contains(g.Id)).ToListAsync(); foreach (var group in groups) group.State = content.Groups[group.Id]; db.ReportRestores.Add(new() { ResetId = reset, Actor = Reports.Actor(c.User), Reason = i.Reason }); Reports.Touch(report); await svc.Reapproval(report, c.User); svc.Log(c.User, id, reset.ToString(), "ReportResetRestored", after: content, reason: i.Reason); return Api.View(report); }));
    }
}
